    report = checkpoint_chain_checkpoint_bundle_diff(_bundle_before(), after)
    (change,) = report["changes"]
    assert change["id"] == "beta"
    assert change["kind"] == "removed"
    assert change["before"] == _bundle_before()["proofs"][-1]["proof"]
