    report = _evolution()
    report["stages"][2]["previous"] = "f" * 64
    assert (
        verify_checkpoint_chain_checkpoint_bundle_evolution(
            report, _expected(report)
        )
        is False
    )


def test_false_root_returns_false():
    report = _evolution()
    report["root"] = "f" * 64
    assert (
        verify_checkpoint_chain_checkpoint_bundle_evolution(
            report, _expected(report)
        )
        is False
    )


